/** @jsxImportSource preact */
import { useEffect, useRef } from "preact/hooks";
import { mountGlassTabMenu, type GlassTabMenuOptions } from "../../components/glass-tab-menu/GlassTabMenuEngine.js";
import type { MotionController } from "../../components/glass-tab-menu/motion-runtime";

export function GlassTabMenu({ options, className }: { options?: GlassTabMenuOptions; className?: string }) {
  const host = useRef<HTMLDivElement>(null);
  const controller = useRef<MotionController | null>(null);
  useEffect(() => {
    const instance = mountGlassTabMenu(host.current!, options);
    controller.current = instance;
    return () => { instance.destroy(); controller.current = null; };
    // Options are updated below without remounting the state machine.
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, []);
  useEffect(() => { controller.current?.update(options ?? {}); }, [options]);
  return <div ref={host} className={className} data-motion-component="glass-tab-menu" />;
}

